/* MSG-01 · Panel de contenido — CSS Module.
   Los colores salen de los tokens de design-system.md §1. Donde la paleta no
   trae blanco puro se usa el neutro de superficie clara más próximo y se marca
   en el sitio. */

.panel {
  /* El shell (bwcnt) ya aporta el padding y el scroll del área de contenido;
     aquí solo se evita que la pantalla colapse su ancho dentro del flex. */
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin: 0 0 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
  margin: 0;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  /* Sin token de blanco puro: surface-mist es el neutro claro más próximo al
     fondo blanco del input aprobado. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* Ídem ThreadList: sin token de blanco, warm-cream es el texto más claro. */
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.primaryBtn:hover:not(:disabled) {
  opacity: 0.88;
}

.primaryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.threadCount {
  margin-left: auto;
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.loading {
  padding: 32px 24px;
  text-align: center;
  font-size: 14px;
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.error {
  padding: 14px 16px;
  font-size: var(--bw-size-input);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  color: var(--bw-sensitive-text);
}

.error p {
  margin: 0;
}

.errorDetail {
  margin-top: 4px;
  font-size: 12px;
  opacity: 0.9;
}

.noResults {
  padding: 32px 24px;
  text-align: center;
  font-size: 14px;
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: all 0.12s;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn.ctrl {
  color: var(--bw-input-placeholder);
}

.pageBtn.active {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  /* Ídem: texto casi blanco sobre deep-steel, warm-cream es el más claro. */
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageBtn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ellipsis {
  min-width: 24px;
  text-align: center;
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

