import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  type ThreadSummary,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * F-118: la firma pública la cablea App.tsx después de escribirse esta tarea.
   * MSG-02 no existe cuando esto se escribe, así que la prop se recibe y se
   * ignora a propósito: abrir un hilo no lleva a ninguna parte en el MVP.
   */
  onOpenThread?: (threadId: string) => void;
}

/** Ventana de números de página, con elipsis cuando hay muchas. */
function buildPageNumbers(current: number, total: number): (number | '…')[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  if (current <= 4) return [1, 2, 3, 4, 5, '…', total];
  if (current >= total - 3) return [1, '…', total - 4, total - 3, total - 2, total - 1, total];
  return [1, '…', current - 1, current, current + 1, '…', total];
}

export function Messages({ profile, now = new Date(), onOpenThread }: MessagesProps) {
  // F-118: recibida y descartada a propósito. El repo no compila sin ella porque
  // App.tsx la pasa, y este fichero es el único sitio donde puede declararse.
  void onOpenThread;

  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : 'No se pudieron cargar los hilos.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const pages = pageCount(total);

  const handleSearchSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSearch(searchInput.trim());
    setPage(1);
  };

  const goToPage = (next: number) => {
    if (next >= 1 && next <= pages) setPage(next);
  };

  const searching = search.trim() !== '';
  const noResults = !error && !loading && searching && threads.length === 0;

  return (
    <div className={styles.panel}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSearchSubmit}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
          />
          <button type="submit" className={styles.srOnly}>Buscar</button>
        </form>

        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          aria-label="Nuevo contacto"
          title="El Directorio de Organizaciones está fuera del alcance de esta versión del MVP."
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
          <span className={styles.srOnly}>Directorio de organizaciones fuera del MVP</span>
        </button>

        <span className={styles.threadCount}>
          {total.toLocaleString('es-ES')} {total === 1 ? 'hilo' : 'hilos'} · Página {page} de {pages}
        </span>
      </div>

      {error ? (
        <div className={styles.error} role="alert">
          <p>No se pudieron cargar los hilos.</p>
          {error !== 'No se pudieron cargar los hilos.' && (
            <p className={styles.errorDetail}>{error}</p>
          )}
        </div>
      ) : noResults ? (
        <div className={styles.noResults} role="status">
          No se encontraron hilos para «{search}».
        </div>
      ) : loading && threads.length === 0 ? (
        <div className={styles.loading} role="status">Cargando hilos…</div>
      ) : (
        <ThreadList threads={threads} now={now} onOpen={() => {}} />
      )}

      {!error && threads.length > 0 && (
        <nav className={styles.pagination} aria-label="Paginación de hilos">
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.ctrl}`}
            disabled={page === 1}
            onClick={() => goToPage(page - 1)}
            aria-label="Página anterior"
          >
            ‹
          </button>
          {buildPageNumbers(page, pages).map((p, idx) =>
            typeof p === 'number' ? (
              <button
                key={p}
                type="button"
                className={`${styles.pageBtn} ${p === page ? styles.active : ''}`}
                aria-current={p === page ? 'page' : undefined}
                onClick={() => goToPage(p)}
              >
                {p}
              </button>
            ) : (
              <span key={`ellipsis-${idx}`} className={styles.ellipsis}>…</span>
            ),
          )}
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.ctrl}`}
            disabled={page === pages}
            onClick={() => goToPage(page + 1)}
            aria-label="Página siguiente"
          >
            ›
          </button>
        </nav>
      )}
    </div>
  );
}

