/* MSG-01 · Lista de Hilos — CSS Module.
   Los colores salen de los tokens de design-system.md §1. Hay dos casos donde la
   paleta no trae blanco puro; se usa el neutro de superficie clara más próximo y
   se marca en el sitio. */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  /* La tarjeta aprobada es blanca; la paleta no trae blanco puro, así que se
     usa el neutro de superficie clara más próximo. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  border-bottom: 1px solid var(--bw-divider-mist);
  background: transparent;
  cursor: pointer;
  text-align: left;
  font-family: var(--bw-font-body);
  transition: background 0.1s;
}

.row:last-child {
  border-bottom: none;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.tsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.bot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-hint-steel);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.empty {
  padding: 48px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyText {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.directoryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* Sin token de blanco puro: warm-cream es el tono más claro de la paleta y el
     que el shell ya usa para texto sobre superficies de color. */
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
}

.directoryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

