import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/** Clase CSS del badge según el tono que deriva el estado. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface ThreadListProps {
  /** Hilos ya ordenados por el servidor: se pintan en el orden recibido. */
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** Avisa con el id del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty} role="status">
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button
          type="button"
          className={styles.directoryBtn}
          disabled
          aria-label="Ir al Directorio"
          title="El Directorio de Organizaciones está fuera del alcance de esta versión del MVP."
        >
          Ir al Directorio
          <span className={styles.srOnly}>Directorio de organizaciones fuera del MVP</span>
        </button>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneCls = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id}>
            <button
              type="button"
              className={styles.row}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.top}>
                <span className={styles.org}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.country}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <span className={styles.tsRow}>
                <time className={styles.ts} dateTime={thread.lastItemAt}>
                  {relativeTime(thread.lastItemAt, now)}
                </time>
              </span>
              <span className={styles.bot}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.badge} ${toneCls}`}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
